package com.yourapp.iptv.data.backup

import androidx.datastore.preferences.core.mutablePreferencesOf
import com.yourapp.iptv.data.datastore.HomeAppearanceCodec
import com.yourapp.iptv.data.profile.ProfileCodec
import com.yourapp.iptv.domain.model.*
import com.yourapp.iptv.domain.profile.*
import org.junit.Assert.*
import org.junit.Test

class ChannelBrowserBackupTest {
    @Test fun aPreChangeCanonicalHomePayloadStillImportsWithItsOriginalBytesAndDefaults() {
        // Literal schema from before channel_layout/channel_logos existed, not generated by the new codec.
        val old = mapOf(
            "language" to BackupValue(BackupValueType.STRING, "GERMAN"),
            "sidebar_side" to BackupValue(BackupValueType.STRING, "LEFT"),
            "expanded_sidebar" to BackupValue(BackupValueType.BOOLEAN, "false"),
            "columns" to BackupValue(BackupValueType.INT, "4"),
            "restore_browse_session" to BackupValue(BackupValueType.BOOLEAN, "true"),
            "color_theme" to BackupValue(BackupValueType.STRING, "RED"),
            "is_dark_theme" to BackupValue(BackupValueType.BOOLEAN, "true"),
            "night_mode" to BackupValue(BackupValueType.BOOLEAN, "false"))
        val payload = backupPayload().let { it.copy(areas = it.areas + (BackupStore.HOME to old)) }
        val decoded = BackupPayloadCodec.decode(BackupPayloadCodec.encode(payload))
        assertEquals(old, decoded.areas.getValue(BackupStore.HOME))
        val home = HomeAppearanceCodec.decode(BackupPreferenceCodec.preferences(old))
        assertEquals(HomeChannelLayout.GRID, home.channelLayout); assertTrue(home.showChannelLogos)
        assertEquals(4, home.columns); assertEquals(HomeLanguage.GERMAN, home.language)
    }

    @Test fun globalAndPersonalBrowserSettingsRoundTripWithoutCrossingProfileNamespaces() {
        val id = "12345678-1234-1234-1234-123456789abc"
        val privateHome = HomeAppearance(profileId = id, columns = 5, theme = HomeTheme.RED,
            channelLayout = HomeChannelLayout.LIST, showChannelLogos = false)
        val people = UserProfiles(entries = UserProfiles().entries + UserProfile(id, "Synthetic", home = privateHome,
            player = PlayerAppearance(profileId = id)), activeId = id)
        assertEquals(people, ProfileCodec.decode(ProfileCodec.encode(people)))
        val prefs = mutablePreferencesOf()
        val global = HomeAppearance(language = HomeLanguage.GERMAN, columns = 4, showChannelLogos = false)
        HomeAppearanceCodec.encode(prefs, global)
        val original = backupPayload().let { it.copy(profiles = people.entries,
            areas = it.areas + (BackupStore.HOME to BackupPreferenceCodec.values(prefs))) }
        val decoded = BackupPayloadCodec.decode(BackupPayloadCodec.encode(original))
        assertEquals(original, decoded)
        assertEquals(privateHome, decoded.profiles.last().home)
        assertEquals(global, HomeAppearanceCodec.decode(BackupPreferenceCodec.preferences(decoded.areas.getValue(BackupStore.HOME))))
    }
}